
function parseUniversalScriptLines(reply, defaultSpeaker) {
  if (!reply) return [];
  let t = reply.trim().replace(/<think>[\s\S]*?<\/think>/gi, "").trim();
  const codeBlockMatch = t.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (codeBlockMatch) {
    t = codeBlockMatch[1].trim();
  }
  let parsed = null;
  try {
    parsed = JSON.parse(t);
  } catch (e) {
    const firstObj = t.indexOf("{");
    const lastObj = t.lastIndexOf("}");
    const firstArr = t.indexOf("[");
    const lastArr = t.lastIndexOf("]");
    if (firstArr !== -1 && lastArr !== -1 && (firstObj === -1 || firstArr < firstObj)) {
      try {
        const arrStr = t.substring(firstArr, lastArr + 1).replace(/,\s*\]/g, "]");
        parsed = JSON.parse(arrStr);
      } catch (e2) {}
    }
    if (!parsed && firstObj !== -1 && lastObj !== -1) {
      try {
        const objStr = t.substring(firstObj, lastObj + 1).replace(/,\s*\}/g, "}");
        parsed = JSON.parse(objStr);
      } catch (e3) {}
    }
  }

  let rawLines = null;
  if (Array.isArray(parsed)) {
    rawLines = parsed;
  } else if (parsed && typeof parsed === "object") {
    rawLines = parsed.lines || parsed.script || parsed.dialogues || parsed.dialogue || parsed.scenes || parsed.story || parsed.content || parsed.data;
  }

  if (!rawLines || !Array.isArray(rawLines) || rawLines.length === 0) {
    console.warn("[UniverseScript] 启用智能行文本兜底提取:", t);
    const splitLines = t.split("\n").map(l => l.trim()).filter(Boolean);
    const fallbackLines = [];
    splitLines.forEach(line => {
      if (line.startsWith("{") || line.startsWith("}") || line.startsWith("[") || line.startsWith("]")) return;
      const colonMatch = line.match(/^[\[【(（]?([^\s\]】)）:：]{1,15})[\]】)）]?[:：]\s*([\s\S]*)$/);
      if (colonMatch) {
        fallbackLines.push({
          type: "dialogue",
          speaker: colonMatch[1].replace(/^[“"「『]+|[”"」』]+$/g, "").trim(),
          text: colonMatch[2].replace(/^[“"「『]+|[”"」』]+$/g, "").trim()
        });
      } else {
        fallbackLines.push({
          type: "narration",
          text: line
        });
      }
    });
    rawLines = fallbackLines;
  }

  return (rawLines || []).map(item => {
    if (typeof item === "string") {
      const match = item.match(/^[\[【(（]?([^\s\]】)）:：]{1,15})[\]】)）]?[:：]\s*([\s\S]*)$/);
      if (match) {
        return { bg: "", sprite: "", name: match[1].trim(), text: match[2].trim() };
      }
      return { bg: "", sprite: "", name: "", text: item.trim() };
    }
    const isDiag = item.type === "dialogue" || item.speaker || item.name || item.role;
    const spk = item.speaker || item.name || item.role || defaultSpeaker || "";
    return {
      bg: item.bg || "",
      sprite: item.sprite || "",
      name: isDiag ? spk : "",
      text: item.text || item.content || item.dialogue || ""
    };
  }).filter(l => l.text && l.text.trim());
}
window.parseUniversalScriptLines = parseUniversalScriptLines;

