              cleanJson = cleanJson.replace(/^```(?:json)?/gi, "").replace(/```$/gi, "").trim();
              const jsonMatch = cleanJson.match(/\{[\s\S]*\}/);
              if (jsonMatch) cleanJson = jsonMatch[0];

              let aiOutput = {};
              try {
                aiOutput = JSON.parse(cleanJson);
              } catch (err) {
                console.warn("AI输出JSON解析失败，启动正则容错提取:", err);
                aiOutput = {
                  thought: cleanJson.slice(0, 120),
                  textColor: "#3E2723",
                  textFontSize: 14.5,
                  stickers: [{ sticker: "🌸", x: 40, y: 35, fontSize: 28 }],
                  shapes: [{ shapeType: "heart", x: 290, y: 40, w: 34, h: 34, color: "#E74C3C" }],
                  sketch: null
                };
              }

              // Canvas 离屏合成
              const offCanvas = document.createElement("canvas");
              offCanvas.width = 360;
              offCanvas.height = 330;
              const ctx = offCanvas.getContext("2d");

              ctx.fillStyle = "rgba(255, 253, 248, 0.96)";
              ctx.fillRect(0, 0, 360, 330);

              ctx.strokeStyle = "rgba(214, 114, 75, 0.14)";
              ctx.lineWidth = 1;
              ctx.strokeRect(10, 10, 340, 310);
              ctx.strokeRect(14, 14, 332, 302);

              ctx.font = "12px serif";
              ctx.fillStyle = "rgba(180, 140, 90, 0.45)";
              ctx.fillText("💮", 20, 28);
              ctx.fillText("💮", 328, 28);
              ctx.fillText("💮", 20, 315);
              ctx.fillText("💮", 328, 315);

