                    ctx.bezierCurveTo(x + w / 2, y + h * 0.2, x + w * 0.6, y, x + w * 0.75, y + h * 0.1);
                    ctx.bezierCurveTo(x + w, y + h * 0.25, x + w * 0.9, y + h * 0.5, x + w / 2, y + h * 0.8);
