const dbName = "t13-stats-db";
const dbVersion = 1;
const initDB = () => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(dbName, dbVersion);
    request.onerror = () => reject("\u6570\u636E\u5E93\u6253\u5F00\u5931\u8D25");
    request.onsuccess = () => resolve(request.result);
    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains("stats")) {
        db.createObjectStore("stats", { keyPath: "id" });
      }
      if (!db.objectStoreNames.contains("analyses")) {
        db.createObjectStore("analyses", {
          keyPath: "id",
          autoIncrement: true
        });
      }
    };
  });
};
const saveData = async (data) => {
  try {
    const db = await initDB();
    const transaction = db.transaction("stats", "readwrite");
    const store = transaction.objectStore("stats");
    await store.put({
      id: "t13-stats",
      ...data,
      updatedAt: (/* @__PURE__ */ new Date()).toISOString()
    });
    transaction.oncomplete = () => db.close();
  } catch (error) {
    console.error("\u4FDD\u5B58\u6570\u636E\u5931\u8D25:", error);
  }
};
const loadData = async () => {
  try {
    const db = await initDB();
    const transaction = db.transaction("stats", "readonly");
    const store = transaction.objectStore("stats");
    const request = store.get("t13-stats");
    return new Promise((resolve) => {
      request.onsuccess = () => {
        db.close();
        resolve(request.result || null);
      };
      request.onerror = () => {
        db.close();
        resolve(null);
      };
    });
  } catch (error) {
    console.error("\u8BFB\u53D6\u6570\u636E\u5931\u8D25:", error);
    return null;
  }
};
const saveAnalysis = async (analysis) => {
  try {
    const db = await initDB();
    const transaction = db.transaction("analyses", "readwrite");
    const store = transaction.objectStore("analyses");
    await store.add({
      ...analysis,
      createdAt: (/* @__PURE__ */ new Date()).toISOString()
    });
    transaction.oncomplete = () => db.close();
  } catch (error) {
    console.error("\u4FDD\u5B58\u5206\u6790\u5931\u8D25:", error);
  }
};
const loadAnalyses = async () => {
  try {
    const db = await initDB();
    const transaction = db.transaction("analyses", "readonly");
    const store = transaction.objectStore("analyses");
    const request = store.getAll();
    return new Promise((resolve) => {
      request.onsuccess = () => {
        db.close();
        resolve(request.result || []);
      };
      request.onerror = () => {
        db.close();
        resolve([]);
      };
    });
  } catch (error) {
    console.error("\u8BFB\u53D6\u5206\u6790\u5386\u53F2\u5931\u8D25:", error);
    return [];
  }
};
