        cell.thiefType = Math.random() < 0.2 ? "thief2" : "thief1";
        const duration = Math.max(0.6, 1.2 - (stage - 1) * 0.1 - (60 - timeLeft) / 60 * 0.3);
        cell.timer = cell.thiefType === "thief2" ? duration * 0.8 : duration;
