const handleGenerateContent = (targetLevel, levels, learnedConcepts, updateActiveCourse, setIsGeneratingCourse, setIsSidebarOpen) => {
  setIsGeneratingCourse(true);
  const sysPrompt = `
    【任务说明】
    请为第 ${targetLevel} 关生成一套闪卡课件。
    1. 关卡需要一个贴合主题的标题 (title) 和一句话简介 (summary)。
    2. 必须生成 8 到 12 个高质量精炼闪卡卡片 (flashcards)。
    3. 闪卡分为两种类型：
       a. 普通类型 (type: "concept")：正面 (concept) 是要学习的具体知识点、词汇或概念。
       b. 填空类型 (type: "fill")：正面是一个包含空白的句子 (sentence)，需要填写正确的答案 (answer)。
                    【任务说明】
                    请为第 ${targetLevel} 关生成一套高质量精炼闪卡课件。
                    1. 关卡需要一个贴合主题的标题 (title) 和一句话简介 (summary)。
                    2. 生成 8 到 10 个精炼闪卡卡片 (flashcards)。
                    3. 闪卡分为两种类型：
                       a. 普通类型 (type: "concept")：正面 (concept) 是要学习的具体知识点、词汇或概念。
                       b. 填空类型 (type: "fill")：正面是一个包含空白的句子 (sentence)，需要填写正确的答案 (answer)。
                    4. 请混合生成两种类型的闪卡，大约各占一半。
                    5. 闪卡背面必须包含：
                       - definition: 严谨简明的解释
                       - example: 一个生动的例句或应用场景
                       - teacherName: 从【授课导师团】中随机指派一位老师的名字来讲解这张卡。
                       - teacherNote: 这位老师的具体讲解。**必须严格符合该老师的性格和语言风格！**可以是吐槽、记忆秘诀、训斥或鼓励。
                    6. 严格返回纯 JSON 对象格式，不要包含 Markdown 标记（如 \`\`\`json ）。

                    【严格的 JSON 返回格式】：
                    {
                      "level": ${targetLevel},
                      "title": "本关精炼标题",
                      "summary": "本关精炼简介",
                      "flashcards": [
                        {
                          "type": "concept",
                          "concept": "概念名称",
                          "pronunciation": "拼音或读音(可选)",
                          "definition": "概念解释",
                          "example": "例句应用",
                          "teacherName": "导师名字",
                          "teacherNote": "导师独家讲解原话"
                        },
                        {
                          "type": "fill",
                          "sentence": "包含空白的句子，例如：_____ 是一种重要的学习方法。",
                          "answer": "重复练习",
                          "definition": "对学习内容进行多次重复以加深记忆的方法",
                          "example": "通过重复练习，我们可以更好地掌握知识点。",
                          "teacherName": "导师名字",
                          "teacherNote": "导师独家讲解原话"
                        }
                      ]
                    }
                  `;
  const userPrompt = `为第 ${targetLevel} 关生成一套包含 8-10 张高质量闪卡的课程内容。`;
  
  if (window.sendToLLM) {
    window.sendToLLM(
      [
        { role: "system", content: sysPrompt },
        { role: "user", content: userPrompt }
      ],
      null,
      (reply) => {
        try {
          let parsedObj = null;
          const cleaned = (reply || "").replace(/```json|```/g, "").trim();

          // 1. 直接尝试 JSON.parse
          try {
            parsedObj = JSON.parse(cleaned);
          } catch (e1) {
            const match = cleaned.match(/\{[\s\S]*\}/);
            if (match) {
              try { parsedObj = JSON.parse(match[0]); } catch (e2) {}
            }
          }

          // 2. 尝试闭合补全截断的 JSON (防止 token 超限未闭合)
          if (!parsedObj || !parsedObj.flashcards || !Array.isArray(parsedObj.flashcards)) {
            const suffixes = ["}", "]}", "]}}", "\"]}", "\"}]}", "\"}}"];
            for (const suffix of suffixes) {
              try {
                const fixed = cleaned.replace(/,\s*$/, "") + suffix;
                const testObj = JSON.parse(fixed);
                if (testObj && (testObj.flashcards || testObj.title)) {
                  parsedObj = testObj;
                  break;
                }
              } catch (eFix) {}
            }
          }

          // 3. 如果解析出的是数组，取第一项
          if (Array.isArray(parsedObj) && parsedObj.length > 0) {
            parsedObj = parsedObj[0];
          }

          // 4. 终极正则恢复提取器（针对模型输出中途截断、字段残缺的情况逐张卡片抢救）
          if (!parsedObj || !Array.isArray(parsedObj.flashcards) || parsedObj.flashcards.length === 0) {
            let recoveredTitle = `第 ${targetLevel} 关`;
            let recoveredSummary = "关卡知识点速记";
            const tM = cleaned.match(/"title"\s*:\s*"([^"]+)"/);
            if (tM) recoveredTitle = tM[1];
            const sM = cleaned.match(/"summary"\s*:\s*"([^"]+)"/);
            if (sM) recoveredSummary = sM[1];

            const cards = [];
            const cardRegex = /\{\s*"(?:type|concept|sentence)"[\s\S]*?\}(?=\s*[,\]\}]|\s*$)/g;
            let m;
            while ((m = cardRegex.exec(cleaned)) !== null) {
              try {
                const cardObj = JSON.parse(m[0]);
                if (cardObj.concept || cardObj.sentence || cardObj.definition) {
                  cards.push(cardObj);
                }
              } catch (e3) {}
            }

            if (cards.length > 0) {
              parsedObj = {
                level: targetLevel,
                title: recoveredTitle,
                summary: recoveredSummary,
                flashcards: cards
              };
            }
          }

          if (parsedObj && Array.isArray(parsedObj.flashcards) && parsedObj.flashcards.length > 0) {
            const newConcepts = parsedObj.flashcards.map((f) => f.concept || f.sentence || "知识点");
            updateActiveCourse({
              levels: [...levels, parsedObj],
              learnedConcepts: [...learnedConcepts, ...newConcepts]
            });
            alert(`第 ${targetLevel} 关《${parsedObj.title || "新章节"}》已生成完毕！`);
          } else {
            throw new Error("数据结构不符或闪卡为空");
          }
        } catch (e) {
          console.error("生成关卡解析失败:", e, reply);
          alert("导师们编写教材时发生了分歧，请重新生成！");
        } finally {
          setIsGeneratingCourse(false);
          setIsSidebarOpen(false);
        }
      },
      (err) => {
        console.error("生成关卡失败:", err);
        setIsGeneratingCourse(false);
        alert("请求失败，请检查API配置！");
      }
    );
  } else {
    alert("未配置API，请前往设置配置！");
    setIsGeneratingCourse(false);
  }
};

