// Global portal state manager
window._bambooModalState = null;
window._bambooModalRoot = null;
window.showBambooModal = (state) => {
  window._bambooModalState = state;
  _renderBambooPortal();
};
window.hideBambooModal = () => {
  window._bambooModalState = null;
  _renderBambooPortal();
};
function _renderBambooPortal() {
  if (!window._bambooModalRoot) {
    try {
      if (window.ReactDOM && window.ReactDOM.createRoot) {
        window._bambooModalRoot = window.ReactDOM.createRoot(_bambooPortalContainer);
      } else if (window.ReactDOM) {
        window._bambooModalRoot = { render: (el) => window.ReactDOM.render(el, _bambooPortalContainer) };
      }
    } catch (e) {
      console.warn('[BambooPortal] ReactDOM not ready:', e);
      return;
    }
  }
  const state = window._bambooModalState;
  if (!state) {
    if (window._bambooModalRoot && window._bambooModalRoot.render) {
      try { window._bambooModalRoot.render(null); } catch (e) {}
    }
    return;
  }
  const el = React.createElement(BambooPortalModal, {
    state,
    onClose: window.hideBambooModal,
    onEnroll: (courseName, character, data) => {
      if (window._bambooEnrollCallback) window._bambooEnrollCallback(courseName, character, data);
    }
  });
  if (window._bambooModalRoot.render) {
    window._bambooModalRoot.render(el);
  }
}

// ==================== 全局辅助：从【传讯-角色配置库】深度提取名士设定 ====================
const getFullCharacterSetting = async (charName, charId) => {
  let char = null;
  try {
    if (window.chatCharacterStore) {
      if (charId) {
        char = await window.chatCharacterStore.get(charId);
      }
      if (!char && charName) {
        const all = await window.chatCharacterStore.getAll();
        char = all.find((c) => c.name === charName || (c.profile?.name && c.profile.name === charName) || (c.realName && c.realName === charName) || (c.name && charName.includes(c.name)));
      }
    }
  } catch (e) {}

  if (!char) {
    try {
      const list = JSON.parse(localStorage.getItem("t8_chat_list") || "[]");
      char = list.find((c) => c.id === charId || c.name === charName || (c.profile?.name && c.profile.name === charName) || (c.name && charName.includes(c.name)));
    } catch (e) {}
  }

  if (!char) return "";

  const lines = [];
  const name = char.name || char.profile?.name || charName;
  lines.push(`【名士姓名】: ${name}`);
  if (char.profile?.gender || char.gender) lines.push(`【性别】: ${char.profile?.gender || char.gender}`);
  if (char.profile?.personality || char.personality) lines.push(`【性格特质】: ${char.profile?.personality || char.personality}`);
  if (char.profile?.speakingStyle || char.speakingStyle || char.profile?.style || char.style) {
    lines.push(`【说话口吻与语言风格（极度重要，100%必须遵从！）】: ${char.profile?.speakingStyle || char.speakingStyle || char.profile?.style || char.style}`);
  }
  if (char.profile?.background || char.background) lines.push(`【身份与生平背景】: ${char.profile?.background || char.background}`);
  if (char.profile?.description || char.description) lines.push(`【立体的角色设定与生平小传】: ${char.profile?.description || char.description}`);
  if (char.profile?.mbti || char.mbti) lines.push(`【MBTI人格】: ${char.profile?.mbti || char.mbti}`);
  if (char.prompt || char.systemPrompt || char.customPrompt || char.profile?.prompt || char.profile?.customPrompt) {
    const rawP = String(char.prompt || char.systemPrompt || char.customPrompt || char.profile?.prompt || char.profile?.customPrompt || "").trim();
    if (rawP) lines.push(`【传讯专属系统提示词（最高优先级遵循）】: ${rawP.slice(0, 1200)}`);
  }

  // 深度读取该名士在角色配置库中挂载的长篇专属设定文档 (characterDocStore)
  const actualId = char.id || charId;
  if (window.characterDocStore && actualId) {
    try {
      const docContext = await window.characterDocStore.getEnabledDocContext(actualId);
      if (docContext && docContext.trim()) {
        lines.push(`【角色专属长篇设定文档】:\n${docContext.trim().slice(0, 1500)}`);
      }
    } catch (e) {}
  }

  return lines.join("\n");
};

// ==================== 学习系统：获取名士私聊、全群聊互动与方天水镜经历 ====================
const getCharacterRecentLearningContext = async (charName, charId) => {
  const parts = [];
  try {
    // 1. 24小时真实传讯私聊记录
    let msgs = [];
    if (window.chatHistoryStore) {
      if (charId) {
        const res = await window.chatHistoryStore.getMessages(charId, 1, 60);
        if (res?.messages?.length) msgs = res.messages;
      }
      if (msgs.length === 0 && charName) {
        const res = await window.chatHistoryStore.getMessages(charName, 1, 60);
        if (res?.messages?.length) msgs = res.messages;
      }
    }
    if (msgs.length === 0) {
      const raw = localStorage.getItem(`t8_chat_history_${charName}`) || (charId ? localStorage.getItem(`t8_chat_history_${charId}`) : null);
      if (raw) {
        try { msgs = JSON.parse(raw) || []; } catch(e) {}
      }
    }

    const oneDayAgo = Date.now() - 24 * 60 * 60 * 1000;
    let recent24h = msgs.filter((m) => {
      const ts = m.timestamp || (typeof m.id === "number" && m.id > 1600000000000 ? m.id : null);
      return ts ? ts >= oneDayAgo : false;
    });
    if (recent24h.length === 0 && msgs.length > 0) {
      recent24h = msgs.slice(-15);
    }
    if (recent24h.length > 0) {
      const chatSnippet = recent24h.slice(-8).map((m) => `${m.isMe ? "用户" : charName}: ${m.text || m.content || ""}`).join("；");
      parts.push(`[与用户的私聊互动]: ${chatSnippet}`);
    }

    // 2. 角色参与的所有群聊动态与名士间互怼记录
    try {
      let allChats = [];
      if (window.chatCharacterStore) {
        allChats = await window.chatCharacterStore.getAll();
      } else {
        allChats = JSON.parse(localStorage.getItem("t8_chat_list") || "[]");
      }
      const groupChats = (allChats || []).filter(c => c && (String(c.id).startsWith("group") || c.type === "group" || c.profile?.members));
      let groupSnippets = [];

      for (const grp of groupChats) {
        if (!grp || !grp.id) continue;
        const grpName = grp.name || grp.profile?.name || "群聊";
        let grpMsgs = [];
        if (window.chatHistoryStore) {
          const res = await window.chatHistoryStore.getMessages(grp.id, 1, 30);
          if (res?.messages?.length) grpMsgs = res.messages;
        }
        if (grpMsgs.length === 0) {
          const raw = localStorage.getItem(`t8_chat_history_${grp.id}`);
          if (raw) {
            try { grpMsgs = JSON.parse(raw) || []; } catch(e) {}
          }
        }

        // 筛选该名士参与或提及该名士的群聊发言
        if (grpMsgs.length > 0) {
          const relatedMsgs = grpMsgs.filter(m => {
            const txt = m.text || "";
            return (m.sender === charName) || txt.includes(`[${charName}]`) || txt.includes(charName) || txt.includes(`@${charName}`);
          });
          const targetGrpMsgs = relatedMsgs.length > 0 ? relatedMsgs.slice(-4) : grpMsgs.slice(-3);
          if (targetGrpMsgs.length > 0) {
            const formatted = targetGrpMsgs.map(m => {
              let t = (m.text || "").replace(/\n+/g, " ").trim();
              if (!t.startsWith("[") && m.sender) t = `[${m.sender}]: ${t}`;
              return t;
            }).join(" | ");
            groupSnippets.push(`【${grpName}】${formatted}`);
          }
        }
      }

      if (groupSnippets.length > 0) {
        parts.push(`[名士在各群聊中的互动发言]: ${groupSnippets.slice(0, 2).join("；")}`);
      }
    } catch (eGrp) {
      console.warn("[Leaderboard] 提取群聊动态失败:", eGrp);
    }

    // 3. 方天水镜生成记录 (手札、太疾驰订单、密信、备忘录)
    if (window.getFangtianMirrorMemory) {
      const mirrorMem = window.getFangtianMirrorMemory(charName);
      if (mirrorMem) {
        parts.push(`[水镜日常行踪与订单]: ${mirrorMem.replace(/\n+/g, " ").trim()}`);
      }
    }
  } catch (err) {
    console.warn("[Leaderboard] 提取名士近况失败:", err);
  }
  return parts.join(" | ");
};

