// ====== 全局提示音与通知分发管理器 ======
window.playNotificationSound = function(type) {
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    const ctx = new AudioCtx();
    if (ctx.state === 'suspended') {
      ctx.resume();
    }
    const now = ctx.currentTime;
    const soundType = type || localStorage.getItem('phone_settings_sound_type') || 'droplet';

    if (soundType === 'droplet') {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(1300, now);
      osc.frequency.exponentialRampToValueAtTime(650, now + 0.05);
      osc.frequency.exponentialRampToValueAtTime(1800, now + 0.12);
      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(0.3, now + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.25);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.26);
    } else if (soundType === 'chime') {
      [1760, 3520].forEach((f, idx) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(f, now);
        gain.gain.setValueAtTime(idx === 0 ? 0.25 : 0.1, now);
        gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.75);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(now);
        osc.stop(now + 0.8);
      });
    } else if (soundType === 'ethereal') {
      [1046.5, 1318.5].forEach((f, i) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(f, now + i * 0.04);
        gain.gain.setValueAtTime(0, now + i * 0.04);
        gain.gain.linearRampToValueAtTime(0.22, now + i * 0.04 + 0.02);
        gain.gain.exponentialRampToValueAtTime(0.001, now + i * 0.04 + 0.38);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(now + i * 0.04);
        osc.stop(now + i * 0.04 + 0.4);
      });
    } else if (soundType === 'harp') {
      [880, 1108.7, 1318.5, 1760].forEach((f, i) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'sine';
        const startT = now + i * 0.06;
        osc.frequency.setValueAtTime(f, startT);
        gain.gain.setValueAtTime(0.18, startT);
        gain.gain.exponentialRampToValueAtTime(0.001, startT + 0.45);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(startT);
        osc.stop(startT + 0.5);
      });
    } else if (soundType === 'chirp') {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(1500, now);
      osc.frequency.exponentialRampToValueAtTime(2400, now + 0.08);
      osc.frequency.exponentialRampToValueAtTime(1900, now + 0.16);
      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(0.25, now + 0.03);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.22);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.23);
    }
  } catch (e) {
    console.warn("播放提示音失败:", e);
  }
};

// ====== 逐条连续瀑布轻弹通知分发器 ======
window.__notifSoundLastPlay = 0;
window.notifyIncomingMessage = function(info) {
  try {
    if (!info || !info.chatId) return;
    const isBannerEnabled = localStorage.getItem('phone_settings_notification_enabled') !== 'false';
    if (!isBannerEnabled) return;

    // 免打扰规则：若当前正处于该聊天详情页，不弹顶部横幅
    if (window.__IS_MSG_APP_OPEN && String(window.__CURRENT_ACTIVE_CHAT_ID) === String(info.chatId)) {
      return;
    }

    // 支持 messages 数组多条批量发送，或单条 text
    let msgsToSend = [];
    if (Array.isArray(info.messages) && info.messages.length > 0) {
      msgsToSend = info.messages;
    } else if (info.text) {
      msgsToSend = [{ text: info.text, senderName: info.senderName, senderAvatar: info.senderAvatar }];
    }

    if (msgsToSend.length === 0) return;

    msgsToSend.forEach((item, index) => {
      setTimeout(() => {
        // 再次检查免打扰
        if (window.__IS_MSG_APP_OPEN && String(window.__CURRENT_ACTIVE_CHAT_ID) === String(info.chatId)) {
          return;
        }

        // 播放提示音（节流控制，最小间隔 380ms）
        const isSoundEnabled = localStorage.getItem('phone_settings_sound_enabled') !== 'false';
        const now = Date.now();
        if (isSoundEnabled && now - window.__notifSoundLastPlay > 380) {
          window.__notifSoundLastPlay = now;
          window.playNotificationSound();
        }

        // 派发单条新消息事件
        window.dispatchEvent(new CustomEvent('phone-incoming-message', {
          detail: {
            id: 'notif-' + Date.now() + '-' + Math.random().toString(36).substring(2, 7),
            chatId: info.chatId,
            senderName: item.senderName || info.senderName || '名士',
            senderAvatar: item.senderAvatar || info.senderAvatar || '',
            text: item.text || '发来一条新消息',
            totalInBatch: msgsToSend.length,
            batchIndex: index + 1,
            timestamp: Date.now()
          }
        }));
      }, index * 600); // 间隔 600ms 逐条瀑布轻弹弹出
    });
  } catch (e) {
    console.error("触发瀑布消息通知失败:", e);
  }
};

