// ====== 瀑布流多卡片顶部通知横幅容器 ======
const GlobalNotificationBanner = () => {
  const [notifs, setNotifs] = React.useState([]);

  React.useEffect(() => {
    const handleIncoming = (e) => {
      const detail = e.detail;
      if (!detail) return;
      setNotifs((prev) => {
        const filtered = prev.filter(n => n.id !== detail.id);
        const next = [...filtered.slice(-2), detail]; // 最多同时堆叠显示 3 条瀑布卡片
        return next;
      });

      // 4.5秒后自动收起
      setTimeout(() => {
        setNotifs((prev) => prev.filter(n => n.id !== detail.id));
      }, 4500);
    };

    window.addEventListener('phone-incoming-message', handleIncoming);
    return () => window.removeEventListener('phone-incoming-message', handleIncoming);
  }, []);

  const handleDismiss = React.useCallback((id) => {
    setNotifs((prev) => prev.filter(n => n.id !== id));
  }, []);

  const handleOpenChat = React.useCallback((chatId) => {
    setNotifs([]);
    if (window.openSpecificChat) {
      window.openSpecificChat(chatId);
    }
  }, []);

  if (notifs.length === 0) return null;

  return React.createElement(
    "div",
    {
      style: {
        position: "fixed",
        top: "14px",
        left: "50%",
        transform: "translateX(-50%)",
        width: "calc(100% - 24px)",
        maxWidth: "420px",
        zIndex: 999999,
        pointerEvents: "none",
        display: "flex",
        flexDirection: "column",
        gap: "8px"
      }
    },
    notifs.map((item) =>
      React.createElement(GlobalNotificationCard, {
        key: item.id,
        item,
        onDismiss: handleDismiss,
        onOpenChat: handleOpenChat
      })
    )
  );
};

