  const [showGroupMemberModal, setShowGroupMemberModal] = useState2(false);
  const [selectedMembers, setSelectedMembers] = useState2([]);
  const [editingChar, setEditingChar] = useState2(null);
  const [showActivitySelect, setShowActivitySelect] = useState2(false);
