                      {
                        "reply": "\u4F60\u60F3\u5BF9\u7528\u6237\u8BF4\u7684\u8BDD\uFF08\u5FC5\u987B\u7B26\u5408\u4F60\u7684\u4EBA\u8BBE\u548C\u8BF4\u8BDD\u98CE\u683C\uFF0C\u5B57\u6570\u4E0D\u8D85\u8FC750\u5B57\uFF09",
                        "action": "none" | "force_change" | "request_change",
                        "songName": "\u5982\u679Caction\u4E0D\u662Fnone\uFF0C\u586B\u5165\u4F60\u60F3\u542C\u7684\u6B4C\u66F2\u540D\u5B57\u6216\u6B4C\u624B\u540D\uFF08\u5982\uFF1A\u5468\u6770\u4F26 \u6674\u5929\uFF09"
                      }

