  const parseLRC = (lrcString) => {
    const lines = lrcString.split(/\r?\n/);
    const result = [];
    const timeExp = /\[(\d{2,}):(\d{2})(?:\.(\d{2,3}))?\]/;
    let hasTimeTags = false;
    lines.forEach((line) => {
      const match = timeExp.exec(line);
      if (match) {
        hasTimeTags = true;
        const minutes = parseInt(match[1], 10);
        const seconds = parseInt(match[2], 10);
        const milliseconds = match[3] ? parseInt(match[3], 10) : 0;
        const ms = match[3] && match[3].length === 2 ? milliseconds * 10 : milliseconds;
        const time2 = minutes * 60 + seconds + ms / 1e3;
        const text = line.replace(timeExp, "").trim();
        if (text) result.push({ time: time2, text });
      }
    });
    if (!hasTimeTags) {
      let fakeTime = 0;
      lines.forEach((line) => {
        if (line.trim()) {
          result.push({ time: fakeTime, text: line.trim() });
          fakeTime += 3;
        }
      });
    }
    result.sort((a, b) => a.time - b.time);
    return result.length > 0 ? result : [{ time: 0, text: "\u7EAF\u97F3\u4E50 / \u65E0\u6B4C\u8BCD" }];
  };
